{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Record C30 reports labetalol bioavailability of 33 ± 3% in normal control subjects after oral and intravenous administration, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C67"],
      "claim": "Record C67 reports meperidine systemic availability of 0.57 ± 0.12 in normal male control subjects after oral versus intravenous administration, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C48"],
      "claim": "Record C48 reports labetalol bioavailability of 18% in humans, a numeric value below the 20% threshold; this is the main contradictory evidence."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": ["C48"],
  "decision_summary": "Across ten evidence molecules with high assay-transfer scores, direct IV-comparison oral bioavailability values are predominantly ≥20%, with many in the 30–80% range; the isolated 18% value does not outweigh the consistent positive evidence.",
  "evidence_gaps": [
    "Molecule 2 includes morphine records alongside meperidine/pethidine; morphine-specific records were discounted.",
    "Molecule 4 includes salicylate measurements after aspirin; direct aspirin-specific bioavailability is less consistently reported."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C30", "C67"],
  "revision_action": "initial",
  "supportive_card_ids": ["C30", "C67"]
}

